import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"紫岩易传卷五","description":"紫岩易传 - 紫岩易传卷五","frontmatter":{"title":"紫岩易传卷五","description":"紫岩易传 - 紫岩易传卷五"},"headers":[],"relativePath":"zh/classics/ziyan/006.md","filePath":"zh/classics/ziyan/006.md"}'),r={name:"zh/classics/ziyan/006.md"};function i(n,p,c,_,o,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="紫岩易传卷五" tabindex="-1">紫岩易传卷五 <a class="header-anchor" href="#紫岩易传卷五" aria-label="Permalink to “紫岩易传卷五”">​</a></h1><p>钦定四库全书</p><p>宋张浚撰</p><p>䷪ 乾下兑上</p><p>「夬」：扬于王庭，孚号有厉。告自邑，不利即戎，利有攸往。彖曰：「夬」，决也，刚决柔也。健而说，决而和。「扬于王庭」，柔乘五刚也；「孚号有厉」，其危乃光也。「告自邑，不利即戎」，所尚乃穷也；「利有攸往」，刚长乃终也。五阳长而后用决，何决之难邪？盖一阴在上，以说为体，而内畜贰心，若尧之四凶、舜之有苗，自非群阳用事，君臣同心，其势未易决去。「扬于王庭」，暴白其罪状于天下也。小人用事久，宠固交缔，其迹秘，其根深，非使天下晓然知其恶而莫之应，则呼吸之间，兵戎所起，岂不殆哉！「孚号有厉」，用决之道也。本至公而持以敬慎之谓「厉」，「厉」盖君子为天下心也。夫号令之孚，固有以感动观听，分别善恶矣。君子犹惕然惧不能济，诚恐争难一生，为吾百姓患也。「孚号以厉」，人心可格，刑罚可省，兹又君子之仁欤。反巽为号，乾五阳为「王庭」，阳实为孚。「告自邑，不利即戎」，圣人至戒也。夫道贵德胜，「邑」，内也。「自邑」，谓修德以治内。「戎」，争也，兵也。尚德不尚兵，天心，圣人心，故「不利即戎」。兑西方为戎，五阳同升，德应于乾，何忧不决，故「利有攸往」，往则柔终矣。如「其利且夬」，一阴用事于上，内之小人，外之夷狄，得位得势，为国家害，皆其象也。惟人君有大中至正之德，刚贤协应，政治毕举，则小人退听，不敢擅事，彼为夷狄者，将敛衽服畏之不暇，夬道成矣。序卦曰：「损而不已必益，益而不已必决。」故夫君人者，莫急于损己之学。损己厥德益修，君子毕用，何决而不利哉？非独决小人也，圣人之治夷狄由是也。「健而说，决而和」，谓何？健决，乾刚之德也。无怒之之心曰说，有生之之意曰和，此中正之道也。如是而后能兴大利，除大害。盖夬决之道，譬诸治病，要当使疾去而元气无损，不然后必有忧。读夬而圣人待小人治夷狄之道，可端坐而议矣。兑上为说为和。「孚号有厉」，其危乃光也。谓以决为危，其危乃光。圣人惟忧天下之诚无已，其增修厥德亦无已，故夬道行而天下治，其光莫大也。坤阴尽消，乾道以成，光德著矣。「告自邑，不利即戎」，所尚乃穷也。「利有攸往」，刚长乃终也。圣人以夬为难，丁宁反复，为天下后世言之也。东汉王允、李唐崔嗣远不知易，各以尚兵穷。夫有天下而不知修德，用君子以自强其国，使小人气丧，夷狄心詟，其势不敢不听服，乃切切然兵戎是急，则争难不解，而为天下害滋大，不亦过欤？呜乎！夫夬之为卦，五阳序进于一阴之决，甚易为功也。圣人犹忧之。健必欲用说，决必欲用和，且孚大号于先，俾奸慝消伏，天下不见决之之迹，而默受其利。圣人知夫戎不可启，启则生乱，若此其慎也。圣人之训至矣哉！「刚长乃终」，谓刚进至乾，阴道于是终云。</p><p>象曰：泽上于天，夬。君子以施禄及下。居德则忌，功力争归。惟霈天之泽，不自以为功，则人心悦而天意得。周公东征而归，其施设可见矣。「公孙硕肤，赤舄几几」，周公未尝居德也。「泽上于天」，利泽下施而与天下同之也。古者谓禄曰「天禄」，乾下为禄，乾刚健为德，居德则兑毁随至，曰「居德则忌」。夫居德则必恣情恃功，有悖道逆理事，天下将群起而攻之矣，忌孰大邪？</p><p>初九：壮于前趾，往不胜，为咎。象曰：「不胜」而「往」，咎也。在夬之初，厥德未孚，而果于有行，其理必不能胜。是以君子务强其德，德积类合，天下莫屈，夬孰御哉？初以阳在卦下，德不上应，若从君子之后可也，往奚益乎？呜呼！事君量德尽义而已，逆理躁进，动必招悔，故君子欲有为于夬，莫若反己修德，以俟朋阳之助焉。「坤」一变有「震」，「艮」体为「趾」。</p><p>九二，惕号，莫夜有戎，勿恤。象曰：「有戎勿恤」，得中道也。二居「乾」中，「乾」健不息为「惕」。「乾」九三亦曰：「夕惕若厉。」「号」，先事戒备也。教化素行，礼法刑政素修，皆「惕号」事。「惕号」，君子之恭也，戎乌恤乎？「莫夜」，「莫夜有戎」，变皆仓卒，浮言胥起，未易明也。斯盖众人所甚惧，君子得中，先事备具，尚奚恤乎？吁！夬决非得臣如九二，其不为小人摇动几希矣。二之有功于「夬」，大矣哉！「乾」二位在日为「暮夜」，「兑」上为「有戎」。</p><p>九三，壮于𬱓，有凶。君子夬夬，独行遇雨若濡，有愠，无咎。象曰：「君子夬夬」，终无咎也。</p><p>疾恶见夫颜色之间，恶者其惧，惧则绝而弗通，何以革？何以化？君子有忧天下心，不忍小人毒加于人，其心欲革而化之，其行独，其迹「若濡」，群阳必有疑之者，是以「有愠」。原其用心，则志于决而合于天，故「无咎」。善乎君子之「夬夬」也。然则善论君子者，论其心而不论其迹可矣。「乾」上刚过，为「𬱓」。位兑体下，为「有愠」。应上，上居兑泽先，为「遇雨若濡」。</p><p>九四，臀无肤，其行次且。牵羊悔亡，闻言不信。象曰：「其行次且」，位不当也。「闻言不信」，聪不明也。方君子健决时，四以阳履阴，其位不中，而窃据三阳上为臀无肤，「其行次且」，谓依违迟回，疑有首鼠心也。互巽，巽不果为「次且」。戒之曰：「牵羊悔亡」，必从众阳而后亡悔耳。兑为羊，大壮、夬皆自坤变，有兑体，兑为羊，羊取刚进触物为义。反巽为「闻言不信」。甚矣，夬决之难也。五阳同类以进，谓夬可以决矣。四犹「次且其行」，何哉？盖断大事，决大议，非刚中者莫能为之，而刚中之贤，岂易得邪？周公大告邦君卿士，周不反曰「艰大」，所见盖不同也。周公未尝直抵以罪，丁宁反复，孜孜之敬训，备见于书。然则虽有不同之论，不害为君子，要在察其设心之正不正耳。心本为国，不同何害？四之「次且」？盖若邦君卿士谓「东征」为「艰大」，而非怀奸以动摇国是者乎？不然，何以无凶咎、悔吝辞也？</p><p>九五：苋陆夬夬，中行无咎。象曰：「中行无咎」，中未光也。阳德既盛，用决匪难，犹「苋陆」之易为功也。持中而行，仅以免咎，圣人之戒，一何严哉！盖夫贵说贵和，中以莅之，后必有光。不然，鸟兽之穷容为害。苟使凡为小人者生反侧心，安平之福不易致也。圣人法天用中，是以「无咎」。意圣人以革化小人为大夬，圣人不得已也。不以化而以决，斯九五之所以未光欤！兑阴揜之为未光。苋陆，泽草，至柔脆物。</p><p>上六：无号，终有凶。象曰：「无号」之「凶」，终不可长也。</p><p>君子孚大公而天下信，遂使小人党日消，势日削，天下谁其从之？夫小人据利势在上，犹足以合党欺众，簧鼓天下，惟屈之以道，使天下晓然知其为小人，知其为恶，知其不可复恃，史道斯成。巽上为号。「无号」，莫之应也。在小人凶，在天下吉。小人道穷，其势不能久于上，为有凶。䷫ 巽下乾上 始。女壮，勿用取女。彖</p><p>曰：「垢」，遇也，柔遇刚也。「勿用取女」，不可与长也。天地相遇，品物咸章也。刚遇中正，天下大行也。妒之时义大矣哉！</p><p>姤一阴生而曰「女壮」，其势方兴，足以消阳也。巽为长女，所应失正，遇不以道，譬小人才力有余而容悦苟合，宜辨于早也。且姤虽阴长之卦，而阴阳至理以遇合为贵，特在夫所遇正不正之间。圣人于卦辞首曰「勿用取女」，言女之不正，不可遇也。盖女不正，足以败家，譬诸小人柔巽不正，内挟权术，足以败国。其为遇也，可不畏哉？继之曰：「天地相遇，品物咸章也。刚遇中正，天下大行也。遇之时义大矣哉。」言遇得其正，则功利及于万物，而遇道行乎天下，其为义大矣。阴生于坤午，与乾子迭相终始，万物至此毕趋亨嘉之地。曰「天地相遇，品物咸章」。「刚遇中正」指二五，二五刚中，以中正之道相遇，风化被于天下，天下悉从其中正，若天地之遇然。圣人致意于姤者，可谓至矣。且夫柔遇刚一也，在卦体则「勿用取女」而不可长，在二五则刚遇中正，天下盛行。盖圣人发其两端，示后世君臣相遇之道，俾知一治一乱，本夫所遇之正不正。后之为人上者，可不知察而为之戒也哉？呜呼！自右小人常遇于时，而君子率不遇。姤一阴生乎下，小人将有必遇之势，其事大可畏。苟非君臣刚中，固莫能止而遏之，宜圣人所甚忧，而丁宁垂训也。然小人在下，何因而遇于时乎？在其君有以启之而已。君心刚以正，则正者遇；君心柔以不正，则柔者遇。气之相感，不约而符。姤一阴在内，其象君心之阴已生。君心不刚，则乐其身而忘其民，是以小人得乘间而进，一小人遇，引类以至，天下将受其祸，宜慎矣夫！坤阴变乾，为天地相遇。</p><p>象曰：天下有风，姤，后以施命诰四方。</p><p>风行天下，无所不被，施命法之，是命自天出，而一本于至公，兹盖圣人所以止阴之生也。夫使天下各安其治而日以无事，圣人安用命？惟夫乾道不足，一阴消之，小人害治者生，则必肆其邪说以惑乱天下。圣人忧之，先事告戒，使天下晓然识善恶趋向，知所避就，而纳之于中正。化不足而后有命，命非圣人得已也。盘庚、周公诰书，丁宁反复，不啻慈父母之训，正阴生防微之几。风于万物，有鼓舞生养功。圣人抑阴助阳，若风之行，为命。风在天下，所及者远，为诰四方。</p><p>初六：繋于金柅，贞吉。有攸往，见凶。羸豕孚蹢躅。象曰：「繋于金柅」，柔道牵也。</p><p>金，坚刚物，金柅用止车行。以金柅止车而又繋之，圣人于小人方长，疾之止之，若是其严邪？圣人何恶乎小人？惧为天下生民害也。「贞吉」谓何？止小人莫大于贞，失贞则窥伺乘间，以类窃起，将不可胜制矣。「有攸往，见凶」，不许阴长也。夫阴长则阳消矣，凶孰甚焉？「羸豕孚蹢躅」，盖圣人深明小人情状，发之于先也。夫小人之进，必倚君子以幸用，若循循可与为善者，而蹢躅之性常萌于中，不制之早，其害未易言。乾金为金柅，巽绳直为繋。「豕」，北方畜至阴之物，羸豕象。阴之微，自午以往，蹢躅决矣。曰「孚，孚」，信然之辞也。且姤一阴居初，小人在下而位实处内，有得君志合之势，坤阴将群起而附之。圣人著训，使后之君子谨微而大正其始，用意远矣。</p><p>九二，包有鱼，无咎，不利宾。象曰：「包有鱼」，义不及宾也。遇道贵一，君于臣于民，夫于妇，上于下，其为遇也，不一则「离」。九二以刚中应五，而下比于初阴，初专遇之，有近民而得其心象。夫得民心而天下归之，则道足以制小人而止其进，遇道行矣，故「无咎」。「不利宾」谓四，四初正应，而其位远阴。夫民近之则亲，远之则去，惟九二刚中，以中正之道莅其下，而下归之。民归之在二，四，安得利邪？吁！君臣相遇，本以为民，观「有鱼」、「无鱼」二象，一以「无咎」，一以「凶」。后之为臣，其可不竭尽诚以勤抚其民人也欤？阳包阴为包，巽隐伏为鱼。巽位东南，四居巽上为宾，互兑为义。</p><p>九三，臀无肤，其行次且，厉，无大咎。象曰：「其行次且」，行未牵也。</p><p>阴阳之情以相遇为说。三眷眷然若有意，初之说从，而九二体刚中之德，已实乘之，不敢不从，故曰「臀无肤，其行次且」。「次且」，谓居之不安，且踟蹰其行也。三以刚居位，故虽有从小人心，终自知厉。「厉」，危也。以其危而厉焉，遂无大咎。呜乎！小人不可迩，尚矣。居上位而有迩小人心，则德与名俱丧，为咎孰大？幸三能厉，未牵于初耳。巽为股，为木，三在巽上，为臀无肤。巽进退不果，为「其行次且」。夬九四有互巽体，亦曰「臀无肤，其行次且」云。初曰「柔道牵」，三曰「行未牵」，幸其未牵于初也。</p><p>九四，包无鱼，起凶。象曰：「无鱼」之「凶」，远民也。</p><p>失民何以事上而保其位？阴为民，四初正应而失之，曰「包无鱼」。鱼柔巽隐伏，民象也。且四位近君，人臣必下遇于民而后能上遇于君。民有远志，位其虚矣。吁！人君责任其臣以求治，盖将必使之加惠吾民，以固结天下心。今也在上位而邈然不以民为念而失其心，虽有民与无民同，下将交怨而疾攻之，为国产祸无疑矣。曰「起凶」，四刚过不中，亢满失民，凶自致之也，故曰「起」云。</p><p>九五，以杞包瓜，含章，有陨自天。象曰：九五「含章」，中正也。「有陨自天」，志不舍命也。</p><p>用君子以封殖百姓，且内蕴其美，而严恭寅畏，仰承天心，以降命行事，如是而后阴可复消也。命出于正，若上帝在左右，号令赏罚，惟帝心之顺，曰「自天」。虽然，五何取于「含章」？盖人君惟不自恃其聪明，然后刚中之贤得以展尽底蕴，成君臣相遇之治，而命之所降，率合天心。后世若秦皇、汉武，矜其智能，群下不敢尽情，卒以毒乱天下，遇之失也。虽然，五之「含章」，非谓拱手责成于二，而于君道莫之省也。曰「有陨自天」，盖一本大公之道，以施命于天下，而我之所操者要，所执者大。若五其深得君道之正欤！二居巽中，有刚德，为把。初以柔居巽先，为瓜。乾中为含章。乾为天，巽为命。</p><p>上九，姤其角，吝，无咎。象曰：「姤其角」，上穷吝也。</p><p>刚上曰角。刚亢处上，何以遇？惟远阴，故虽吝无咎。晋上九亦曰「晋其角」。盖居晋遇之极，而刚亢不反，其必穷莫之进，莫之遇矣。䷬ 坤下兑上</p><p>萃亨。王假有庙，利见大人，亨，利贞。用大牲吉，利有攸往。彖曰：「萃」，聚也。顺以说，刚中而应，故聚也。「王假有庙」，致孝享也。「利见大人，亨」，聚以正也。「用大牲吉，利有攸往」，顺天命也。观其所聚，而天地万物之情可见矣。</p><p>国以民为本，民以贤为命。顺以说，得民之心也。「刚中而应」，得贤之心也。得贤斯得民矣，不萃奚为？济涣治萃，得四海欢心，以顺事其先，而教天下以孝，以中合其心，故萃、涣皆曰「假有庙」。坤在内为得民。民说则国家有磐石之安，宗庙之祭可以极尽其诚礼矣，曰「假有庙」。上为宗庙，互体巽木在上，为有庙。利见大人，亨，利贞。何谓贞？若商汤之于伊尹，周武之于太公，为萃之贞。何哉？汤、武、伊、吕之为君臣，志在天下而不在身，是为贞。大人谓五牲何取于用？大萃而归功天地鬼神，内诚外礼，不可不竭尽也。诚礼尽而教化行，故吉。且生民之命在食，人何以聚？曰食而已矣。圣人于萃聚之时，既尽力于民事，报本之礼，牲必用，大有深意其间。盖泽上于地，农事兴矣，所以报本不可后也。坤为牛，曰大牲。兑金在下，曰用。「利有攸往」，谓宜勉修厥德，以有为于天下。夫天命以萃，非德曷承？二阳以刚德相比，刚进上行，其刚得中，往必利矣。互巽为天命，坤下为顺天命，观其所萃，而天地万物之情可见矣。谓天地万物以萃为大，圣人承天地，育万物，不可不求其所以致萃之道，而增修吾之德政，以上承天地之心也。</p><p>象曰：泽上于地，萃，君子以除戎，巽戒不虞。</p><p>既治偃兵，适以启兵，盍若先事有备，可以息奸慝，弭后患乎？今夫泽之储水，一失防范，则决矣。惟水得其防，而泽行于地，然后利泽及物，生养之道兴焉。君子法之，戎器是除，不虞是戒，所以大利泽于后也。而况顺说之极，上恬下熙，安于佚豫，仓卒之变，可不虑哉？君子知聚必有散，安必有危，有国有家，不可一日忘备，其急急夫戎器之除，非曰先武事而后德政也。盖以吾之德政，既有以感说民心而俾之萃，又恐夫害治者起而重为之防，初不敢一日自恃其治焉，则德益修，政益立，天下之萃，不知何时而已也。君子规模远矣哉！兑西方，为戎器，互艮震，震动为不虞，艮手为除，兑口为戎。孔子答子贡问政曰：「足食足兵，民信之矣。」故夫萃聚足食之时，武备不可一日忘于天下。以武傋之不可忘，而不敢安于逸乐，则其为德政之补，亦云大矣。抑卫武公刺厉王诗，其三章曰：「夙兴夜寐，洒扫庭内。修尔车马，弓矢戎兵。用戒戎作，用逖蛮方。」终之曰：「用戒不虞。」武公之学，其有得于易欤！初六，有孚不终，乃乱乃萃。若号，一握为笑，勿恤，往无咎。象曰：「乃乱乃萃」，其志乱也。</p><p>居萃聚之初，信君子，远小人，聚斯光矣。信贵有终，二三其心，合斯离，以此行世，何以立事？知而忧之，终得其应，咎其免焉。君子先定志于内，而后求聚于外，结之以信，持之以久，故志行事立，而能有为于萃聚之时也。初以柔应四，刚柔交孚，于应为得。惟二阴在前，有昵比从类之心，「其孚不终，用乱乃萃」，是欲弃君子而为小人之归者，德必丧矣，何以萃而升哉？「若号」，忧发于声音也。初自兑变，以刚履顺，故能知其过，忧之终得正应，以获一握之笑于后。「勿恤往无咎」，谓所从适之正，自能免咎，不用恤也。呜呼！君子之于聚，不可不慎所孚而勉其终。慎之何如？亦在夫先定其志而已。兑口为号，艮手为握，兑说为笑。</p><p>六二，引吉，无咎。孚乃利用礿。象曰：「引吉无咎」，中未变也。萃贵合，戒在苟合。二居坤阴中，必引而后「吉无咎」。盖君臣之间相遇而不以诚，则信之不笃，任之不专，萃其难矣。夫惟上以诚求，下以诚应，道斯可行。君臣之心交孚若一，弼违补过，中不自疑，故用「礿」为「利」。「礿」，夏祭也，薄祭也。礿之利用，谓至诚可通，心腹可尽，若祭祀之不待备物也。用是居萃，则大利以兴，大功以立，治其盛矣。上说下顺为「引吉」，二五皆中正为「孚」，坤位西南为「礿」。「中未变」谓何？言君子守中于身，不以既萃而轻变其志，必上我求而后应之，谓不如是不足以有为于萃也。</p><p>六三，萃如嗟如，无攸利。往无咎，小吝。象曰：「往无咎」，上巽也。</p><p>求萃而不得志，故「嗟萃」。三处坤顺之极，其位不中，欲上比于阳，而二阴牵之。夫二阳，君子也，若曰小人归而君子不与焉，故「萃如嗟如」，以此事君，何为而利？「嗟」，叹辞也。嗟则知悔矣。往而应上，庶几无咎。盖上方巽身待下，三往应之，犹愈于独行无助于萃也。惜乎上非刚德，终不足与有为，故三于萃「小吝」。吁！聚而君子也，则善日闻，德日进，名日彰，功日兴。小人反是矣，宜三之所以重发叹欤。三位在二阳二阴中，盖处君子小人之间者也。然则三者安可不审择其所与聚？后之求萃于君臣朋友者，宜鉴兹。兑口为嗟。互巽为上巽。</p><p>九四，大吉，无咎。象曰：「大吉无咎」，位不当也。</p><p>四多惧，谓近君也。萃九四以刚阳居萃聚时，德足以说天下，而天下顺服之，祸福安危之几于是乎生，是实德位使然也。惟夫上得于君，下得于民，两者兼之，吉斯大，大吉而后无咎。盖得君而不得民，则道不信于天下，固不可与大有为于天下也。得民矣，君或未之信焉，闲隙疑忌之起，殆不可胜言，终亦何以行其志哉？「萃」四自临来，君臣同德，相说以正，「坤」众顺之，是上得于君，下得于民者也，是以「大吉无咎」。呜呼！以四之「大吉」，仅能免咎于「萃」，古人谓蹈富贵为危机，信矣夫！</p><p>九五：萃有位，无咎。匪孚，元永贞，悔亡。象曰：「萃有位」，志未光也。</p><p>临变而「萃」，九五以刚中为萃主，天下顺应曰「萃有位」，无可咎者，曰「无咎」。盖为「匪孚」，其下刚阻于下，群阴之情未尽通，且五之刚德未立，德未洽于天下心故欤！勉修其德，「萃」其光矣。「元」为众德之先，其用仁也，善也，持以永，守以贞，奚患不孚？汤、武之举，有愧尧、舜，「匪孚」也。若「元永贞」，在二君则优之，故终能得志天下，且有令望于后世。圣人惧萃聚之主，安顺说而忽修德，曰「匪孚」，曰「元永贞悔亡」，戒也。盖五于「萃」有说体，是或以天下归之为己乐，不可不戒；阴揜之为志未光。</p><p>上六：赍咨涕洟，无咎。象曰：「赍咨涕洟」，未安上也。</p><p>处「萃」聚上，说极必反，惟忧所当忧，而诚以求应，始免于咎，圣人至训也。方天下顺说之极，而己身在上位，孰不晏然自以为乐？圣人独以为是大可忧，非至诚省惧，急于得人，若「赍咨涕洟」者然，殆未可免夫祸难。圣人之训微哉！「兑」口为「赍咨」。三阴在下，顺应于阳。上六有失应之忧，曰「未安」。上䷭ 巽下坤上</p><p>「升」，元亨。用见大人，勿恤，南征吉。</p><p>彖曰：柔以时升，「巽」而顺，刚中而应，是以大亨。「用见大人，勿恤」，有庆也。「南征吉」，志行也。</p><p>「临」二阳，五变为「升」。二阳升也，而曰「柔以时升」，盖二阳升于内，刚德浸盛，柔道用得位而上行，曰「柔以时升」。「巽而顺」，有可升之德；「刚中而应」，有可升之资。「刚中」谓二。二以刚中应五，五得二应，而刚德盛于内，是以其亨大曰「元亨」。譬夫木在地中，其本既盛，二阳之气并进上达，木之升也，莫之御矣。且内巽外顺，仁德既行，而又有刚中之应，内强其志，柔之时升，不亦宜乎？自「巽」而「离」，自「离」而「坤」，柔道正位于「离」，而成物于坤，曰「时升」。用见大人，指刚中之阳也。五居尊位，曰「大人」。见大人以趋亨嘉之会，何往不利？曰「勿恤，南征吉」。「巽」在下，「巽」不果，「勿恤」宜戒。「巽」至离，万物皆相见，「南征」之所以「吉」欤？呜呼！读「升」而知君人者，欲德位俱升，亦在勉求刚中之贤而已。诚能巽顺下贤，而吾之刚德日进不已，帝王之治可历阶而至也。虽然，升之用亦大矣。六五柔中，何以为升之主邪？曰：五所谓柔，非志于怠安之柔也。二阳内应，有得贤之益，吾之刚德方浸长于内而未艾，是以能有生养万物之功，而志得行于天下，其升岂不信哉？互「兑」为「有庆」，「坤」进而上为「志行」。</p><p>象曰：地中生木，「升」。君子以顺德，积小以高大。</p><p>山上有木，其进也渐。若木生地中，则阳动于内，停蓄含养之日久，得时而升。升不可测，君子法象，曷取于顺德之积乎？盖德契天人，是谓顺德。顺德既积，斯有以感入天下之心，天下从而化之，自邑至国，自国至天下，德业两大，莫之与并，若木之升矣。古之用此者，其周文王乎？坤、巽皆顺体为顺，二刚居内为「德」，内刚外柔为顺德。</p><p>初六：允升，大吉。象曰：「允升大吉」，上合志也。</p><p>「允」，信也。在己有可信之德，然后获信于上，以是居升，升其合矣。夫在下位者，不患道之不行，而患己德无可信者，惟体「巽」之仁，应坤之顺，二阳既孚，上必我信，斯可与有为于升之时矣。盖阳为君子，君子信己而援之，则上信之；上信之，则天下信之，吉于是乎大。初承二阳以应四，「坤」阴在上，莫不一意下之，曰「允升」。初之「允升」，盖得「巽」仁以应四，而二阳为之援，是以无往不合也。</p><p>九二：孚乃利用礿，无咎。象曰：九二之「孚」，有喜也。</p><p>事君犹事神事天，然舍诚固不能有格也。盖毫发欺愧于中，则精神之感必不交孚，尚何以得君而惠利天下哉？九二以刚德在「巽」中，五顺二「巽」，中道默通曰「孚」。刚贤以中孚君，君德日新，斯可以体至公，亡形迹，竭尽忠嘉，以强其所难，拂其所顺，致君于尧舜之前矣。曰「利用礿」，「礿」，薄祭。夏曰「礿」，贵诚不贵物也。志得道行，君子之喜，曰「有喜」。互「兑」为「喜」。</p><p>九三，升虚邑。象曰：「升虚邑」，无所疑也。</p><p>「坤」上为「邑」，「升」二阳自临来，三有刚德，二又比之，「巽」仁充于内，「坤」众顺于外，仁德感通，邑人之心先归焉。「邑」，我邑也，邑其虚矣，升又何疑？汤武之举则然，士君子巽志入道，收后获功，其进也如虚邑之升，亦在夫勉其不息之刚而已。六四，王用亨于岐山，吉，无咎。象曰：「王用亨于岐山」，顺事也。</p><p>有文王谨守臣节之心乃亨。文王有忧爱天下之诚，而德益进，志益恭，守益正，上天所喜，后世所仰。文王惟顺于天，顺于道，故能顺于君，顺于人，后世莫得而少疵之也。升至九三，已有虚邑象。文王处四位而心不忘顺，纣，眷然日望其迁悔，岂非盛德事欤？不孚奚为？互兑为西山。六五，贞吉，升阶。象曰：「贞吉升阶」，大得志也。</p><p>德合天人为贞。坤以柔升，五坤中而顺德格于上下，刚贤应之，德进不已，升罔不吉，用得志于四海云。坤土为阶，自下而上曰「升阶」，以德为阶也。五之德若是，可与为王，可与为帝矣，故曰「大得志」。盖六五刚德浸长于内，是以其升若此。</p><p>上六，冥升，利于不息之贞。象曰：「冥升」在上，消不富也。向晦曰：冥冥何以升？冥升谓处富贵极至，利欲牵之，于升必冥，非谓以冥获升。利于不息之贞，谓其贞不息，则有出晦之道，犹日月之行地中也。呜呼！自天子至公卿大人，势位既崇，冒昧利欲，不知厌极，其能不丧身而亡家国者几何？惟惕然惧省，以增修夫仁义之道，则无忧乎消不富矣。圣人灼知至理之必然，而为之戒。上六：履阴居巽，顺极为冥升。盖巽顺之至，刚德必衰，晦其宜也。䷮ 坎下兑上 困亨。贞，大人吉，无咎，有言不信。</p><p>彖曰：「困」，刚揜也。险以说，困而不失其所，「亨」，其唯君子乎？「贞，大人吉」，以刚中也。「有言不信」，尚口乃穷也。</p><p>困自否变，时之否矣，君子宜困。君子有乾刚生物之德，而三阴揜之。三阴挟说险之资，外示和易，内蓄奸阻，上下交蔽，复有用事于中，以离间吾君臣心腹者。君子虽有巽仁离明之德，无所用于时，而其道以穷，是以「困」也。困以刚中为贞，惟贞乃亨。大人居困而吉，端在此。盖刚中则能勉进乎道，而明足以见，仁足以守，不为穷达死生变其志，何为不亨哉？「无咎」，谓无可咎。「险以说，困而不失其所，亨」，言君子处险以说，其修身砺行，无愧天人，身虽在险，道自亨也。且困何为而取于说？说谓说于道，非于物而说也。说道者视险无险，其心尚亨。且士君子之有志于道，孰不欲以道为说？惟其养之不粹，行之不力，一为忧患所迫，鲜不戚戚于中。故夫在险能说，其事为难，非刚中者莫克行之。大人指二五，二、五有刚中之德，守贞不挠，困极而通，其事业将大于天下，曰「大人吉，无咎」。「有言不信」，言无益也。兑上为言，坎在下，其道不能上达为不信。夫小人布列于上下内外，以是为非，以正为邪。当是时，其可以口舌争邪？天实为之，尚口则穷，君子修道待时可也。杂卦曰：「井通而困相遇也。」井、坎一在上，困则反之，故在井者其道通，处困者其道穷。序卦曰：「困乎上者必反下。」盖道之为一，浩然常存，初不以困亡，君子何患哉？乐己之道，忘身之困，斯无入不自得，而变穷为通矣。文王、孔子善处困者，文王、孔子道传后世，厥亨孰大？</p><p>象曰：泽无水，困，君子以致命遂志。</p><p>致在天之命，遂在我之志。「致」云者，委之于无可奈何也。道之不行，岂人力也哉？虽然，水未尝一日无也，泽无之而水趋于下，时而已。阳气奋达，泽水必滋。道未尝无一日不在天下也，道之不行，时则使然。君子知之，固穷乐道，自求其志，得时得君，殆将摅素所蕴蓄而行之天下。君子之心，亦岂一日忘君忘天下也邪？其遂志也，时焉而有不得已耳。困自兑变，在卦气正坎水趋下而泽涸之时。</p><p>初六：臀困于株木，入于幽谷，三岁不觌。象曰：「入于幽谷」，幽不明也。</p><p>困三阴有「株木」、蒺藜、「葛藟」象。盖卦体巽木在中，兑一变坎为困，而兑复有互巽体，且自秋徂冬，草木雕落，困之时也。是以爻之取象如此。呜呼！小人之困君子，适足以自困，惜其快一时私意，曾莫悟耳。观三阴皆以草木衰败不振者为况，见圣人之心嫉小人深也。初以柔居坎险下，其应在四，四互体巽，兑金制之。枝叶不敷，无以芘下，曰「株木」。初六从二阴以困君子，君子道穷，天下以否而己。身失芘，将亦不得一日安。曰「臀困于株木」，「臀困」云者，谓不可以有行也。「入于幽谷」，趋险不反也。「三岁不觌」，前有互离，不觌其明也。然则小人暗于天理，惟险之怀，其困君子也，祗以自困，不知其将何所寄六尺之躯于天地间哉？自初至四为三岁。</p><p>九二，困于酒食，朱绂方来，利用享祀。征凶，无咎。象曰：「困于酒食」，中有庆也。</p><p>九二有中和之德，可以养人，而方处险中，德未及施。曰「困于酒食」，九五同德之君，方倾意向之，谓其德之可以通于神明也。曰「朱绂方来，征凶」，时未可为也。君子贵因时，违之则凶，无所可咎。坎中为酒食，「朱绂」谓五。朱阳正色，君道也。二自否来，位本乾体，故「利用享祀」。天曰「祀」，美德可以养天下，为「中有庆」。呜呼！自昔小人困君子，必先离间其君臣之心。六三以阴在内，盖小人用事于中者。幸二五君臣道通，虽困终合，故曰「有庆」云。此非二之庆也，天下之庆也。</p><p>六三，困于石，据于蒺藜，入于其宫，不见其妻，凶。象曰：「据于蒺藜」，乘刚也。「入于其宫，不见其妻」，不𥙶也。「困于石」，揜四五也。「据于蒺藜」，揜二也。四五有笃实之德，三在下而欲困之，是将获罪于天下后世，故名必辱。九二刚中，三窃处其上，怀不自安，天下其起而攻之矣，故身必危。名辱身危，有死之道，不祥莫大。嗟夫！小人幸君子困，行行然贪欲日肆，自以为得，不知获罪天人之深，适足以困己。其名、其身、其家，将不能悉保于后，在彼何利哉？惜夫阴柔不正，日以昧昧，智不知此耳。互体离中，离不当位，「坎」复易之，为「不见其妻」。九四，来徐徐，困于金车，吝，有终。象曰：「来徐徐」，志在下也。虽不当位，有与也。</p><p>车之载物，必获辅于下而后可以有行。君子在困，虽蕴载物之德，非求应于下，则其道亦不能上达矣。四居兑金先，本有乾体，曰「金车」。三以阴间之，坎险在下，莫之能进，以协比于二而求于初，故「其来徐徐」。惟四志在应初，终必有与，虽吝得终也。自外而内曰「来」，巽不果为「徐徐」。呜呼！人臣居四而处近君之位，在夫勉求其应而已。不然，虽有刚强之德，终无以出困而止难也。戒之哉！</p><p>九五，劓刖，困于赤绂，乃徐有说，利用祭祀。象曰：「劓刖」，志未得也。「乃徐有说」，以中直也。「利用祭祀」，受福也。</p><p>人君有刚中至德，而又得刚中之贤，然后可以除间去险，而息天下之困。困二五以刚居上下卦中，而三阴蔽其耳目，离其心腹，使二不得上应于五，曰「困于赤绂」。「赤」，臣道也。「劓刖」，欲施刑于上下之阴，有志而无助，志不得行，是以「困」。惟中直，故「乃徐有说」。盖君臣以中直之道相与，则天人之心可格，何间不除哉？兑上为「说」。「利用祭祀」，谓品物可备，诚礼可尽也。五位兑中，万物盛多时，故于祭祀利用。夫间我者去而君臣相说，则巽仁离明之德，可被于天下，而治道以兴，险难迄平矣。受福于天，夫复何疑也。五本乾位，得贤而天人之心说，曰受福。兑金为劓刖，兑巫为祭祀。绂，相蔽饰之服。二五来自乾，乾为衣。朱、赤皆乾阳色。赤朱之发见于外者，诸侯服也。二五德刚中，曰以中直。</p><p>上六，困于葛藟，于臲卼，曰动悔有悔，征吉。象曰：「困于葛藟」，未当也。「动悔有悔」，吉行也。</p><p>上以阴居兑终，有互巽体二阴牵之，相与揜刚。上位一卦，上逡巡忸怩，若「困于葛藟」而臲卼不自安者。然葛藟柔脆滋蔓，小人相与牵连状也。小人欲困君子，而赧然有歉于心，故臲卼其居。动悔则变而从阳矣。诚能有悔乎，其征斯吉。扬雄曰：侍君子，晦斯光，窒斯通，辱斯荣，败斯成。夫通，君子乃所以自通；困，君子乃所以自困。圣人示动悔之象，使后世为小人者知所以弃恶而趋善也。反巽为臲卼，兑说为吉行。䷯ 巽下坎上</p><p>井，改邑不改井，无丧无得，往来井井。汔至亦未繘井，羸其瓶，凶。</p><p>彖曰：巽乎水而上水，井。井养而不穷也。「改邑不改井」，乃以刚中也。「汔至亦未繘井」，未有功也。「羸其瓶」，是以凶也。静养之功既成，以中守之，以仁出之，俾天下各安性命之情，井之用大矣。坤五下居乾初，坤为邑，邑可改，井不可改，谓坤阴往来坎一不变。盖邑有兴废，而井之在地常自若，譬诸君子有刚中至德，不为天下之动而变其守，惠泽于是生焉。「无丧无得」，中先定也。定故能应，求者应之，随取而与，曰「往来井井」。往来虽不常，而吾之为井，未尝加损耳。困三四易位而成井。在困坎之一潜于下，在井坎之一升于上。困则君子道穷，而利泽不能以上施。井则君子道通，而仁泽徧及于天下。君子德成于井，凡以养之不穷，不为居困而变其心志，故其德益修，其利益大也。且阳中于坎，养以静正，行以巽仁，而其施不匮，井之功用，不亦大哉？汔至，亦未繘井，羸其瓶，凶。圣人勉后之君子，修诚砺器，以大仁德于天下也。盖圣贤以利泽及物为功，惟心诚于内，而后功著于外。「汔至未繘井」而「羸其瓶」焉，诚不至也。巽为绳，为进退，为不果。互兑，互离在中，离中虚，兑毁折，为汔至。未繘井，为羸瓶。</p><p>象曰：木上有水，井，君子以劳民劝相。</p><p>古者设庠序礼乐之教，法度政令之防，非以勤民，盖将诱而纳诸善以辅翼之耳。水得木而功利施，君子以德行仁而天下受惠。孟子载「帝尧忧民，自劳之来」之下，皆劳民劝相义也。坎，劳卦，坤五下降为民，为劳民。互兑，兑言为劝。相劳云者，使之朝夕从事于教化，劝其未至，相其未成也。初六，井泥不食，旧井无禽。象曰：「井泥不食」，下也。「旧井无禽」，时舍也。</p><p>井以污浊废，鸟兽犹去之，而况于人乎？初以柔顺居坎险下，盖不能洁白其德，而自抵于废弃者也。君子恶居下流，凡以失其清明之性故耳。坎水在上，巽入之，兑毁之为泥。互兑为不食。四有离体，与物不相应，为无禽，为时舍。</p><p>九二，井谷射鲋，瓮敝漏。象曰：「井谷射鲋」，无与也。士君子必有圣贤之与，厥德乃修。二不获上应于五，而下比初阴，趋向不正，德以之堕，曰「井谷射鲋，瓮敝漏」。位居坎险下为谷，巽为鲋。鲋，鱼细者。坤五下居初，坤土在下，兑毁乘之，为瓮敝漏。二本刚中，而以顺说之资，下比于阴，弃中正，从昏浊，刚德既亏，才器沦丧，惜哉！虽然，为二者亦在夫求与己修己而已。圣人不著凶咎辞，幸二一朝反身而从善也。</p><p>九三，井渫不食，为我心恻，可用汲，王明，并受其福。象曰：「井渫不食」，行恻也。求王明，受福也。</p><p>九三备清洁之德，而位在坎后，小人蔽之，王明则蔽者退矣，故「并受其福」。夫井之为水，善利万物，凡以至洁而已。传曰：「气之清者为贤。」三有可食之德而不及食，孰不恻然念之？「可用汲」，宜在高位之谓。君子而在高位，惠泽必加于天下，汲可用也。巽上巽洁齐，为井渫，兑毁为不食。坎加忧为心恻。上应之，为可用汲。五以乾德居互离上，为王明。曰「求」云者，德修于己，君子求之，是以不求求之也。天下被泽为受福，盖君臣之福系在天下，阳为福。</p><p>六四，井甃，无咎。象曰：「井甃无咎」，修井也。</p><p>德莫大夫养之修之，修之所以大其养。井六四位在坎下，互体离兑，兑毁离明，明足以有见，故能先毁而用其修云。是可以塞近臣之责矣，曰「无咎」。且人臣修己之德，以修其君之德，君德既修，善政斯出，其利岂浅浅哉？坎离有水，火用为甃。九五，井冽寒泉，食。象曰：「寒泉」之食，中正也。</p><p>居中履正，美德厌天下心，若寒泉足以息天下之热者然。曰「井冽寒泉食」，夫中正本之身，达之天下，人君诚能恭己无为，以行吾之中正，则天下莫不日用而默化之，相与去恶从善，如渴得饮，热以寒息，惠所及者大矣。坎中为冽，阳萌黄钟，泉所自发，潜养之功非一日，曰「寒泉」。泉寒而天下喜食之，犹圣贤有美德，天下仰惠，斟酌饱满，各得其欲也。五以坎中居互离上，中正而明，有静一之德，故其取象如此。</p><p>上六，井收勿幕，有孚，元吉。象曰：「元吉」在上，大成也。井道既成，曰「井收勿幕」。「勿幕」，戒也。上以阴居井上，阴性吝啬，宜戒。圣人一视同仁，方且公天下而惠利之。天下求之无穷已，而圣人与之亦无穷已，岂曰幕之云哉？圣人有诚一之德，饮德者莫不率化，不劳而惠自及之，所孚者大矣。虞舜、文王行此，舜以正，文王以渊懿。向使二圣人敛德弗用，天下安所系命哉？舜、文王之心不一日忘天下，故天下后世乐推其德而不厌也。阴上为收，坎北方为有孚。其吉以仁，曰「元吉」。元吉，吉之大也。䷰ 离下兑上</p><p>革，巳日乃孚，元亨，利贞，悔亡。</p><p>彖曰：革，水火相息，二女同居，其志不相得，曰「革」。「巳日乃孚」，革而信之。文明以说，太亨以正。革而当，其悔乃亡。天地革而四时成，汤武革命，顺乎天而应乎人。革之时大矣哉！</p><p>火动而上，泽动而下，二女志不同行为睽。睽离之义也。至泽火相息，而志不相得，事势既穷，不可一朝居矣，曰「革」。序卦曰：「井道不可不革，故受之以革。」易污浊而为清明，革道也。虽然，有乾德而后可革。革非易事也，必德明而有以孚信之于先，然后革可用。德之能孚，非一日事，曰「巳日乃孚」，革而信之。孚而后革，圣人不轻为也。元亨利贞，乾德也。互体乾在中，故曰「元亨利贞」云。悔亡，谓不获罪于天人也。离为日，自初进四，革道乃成，为巳日。周自后稷至太王、王季、文王，德孚天下久矣。武王继之，始用革，孚而革也。惟汤之革夏亦然。呜呼！革非德明著见之君，莫能行之矣。水火相息，二女同居，其志不相得，曰「革」。圣人甚言革之不得已也。水火陵害，生理绝灭，其势有不得不大变之，以惠利天下万物者。火炎上而泽息之，泽趋下而火息之，曰相息。夫卦体泽火也，而曰「水火相息」，盖水火在天地间，未尝一日无之，故水在火上为既济，蔑有息也。若泽火则质性不同，泽金为水母，夫泽，水所钟也，水在泽而火克之，金日以消，水日以涸，火日以衰，其势必息。自离午至兑酉，水火败绝之时，兑金又为死火所克，宜其息。卦以坎变至震，革始用事。震，仁也，圣人必俟仁德之孚而后革也。兑离索于乾而得，曰「同居」，居同而志不相得，则上下侵夺，将不得以生养，是岂可不革哉？虽然，革，金火之变也，圣人用土之信以济革，曰「革而信之」，何以言邪？稽诸时运，方火金相息之时，得未土以生金，土承火母生金子，于是有庚伏之候，而岁功以成。圣人出而应天下之革，非信固无以服亿兆心，拯之涂炭中也，故曰「革而信之」云。文明以说，大亨以正。革而当，其悔乃亡。谓顺天人之心，其革必当。不然，利未及兴，而害已随起矣。当仅悔亡，不当之害可胜言邪？君子慎革，惟德之文明，而天人胥说，亨大以正，然后革可为也。天地革而四时成，汤武革命，顺乎天而应乎人。革之时大矣哉！圣人因天地以明革也。天地以生物为心，其革也，所以成四时，而生物之功于是不穷。春夏生养，秋冬肃杀，循环致用，于以见天地之仁。汤、武法天，拯天下于涂炭中，而纳之于仁寿之域。汤武之心配天地，革于时为大，殆未可轻议也。</p><p>象曰：泽中有火，革；君子以治历明时。</p><p>君子之革，本以顺天。君子观泽火象治历，盖将与天下同奉天地之革，敬授而日月之也。是其设施举措，凡有因革于天下，罔不稽于天而协于人矣。卦自坎变，坎离，日月之会，而泽火相息，久必差忒，历不可不治也。</p><p>初九，巩用黄牛之革。象曰：「巩用黄牛」，不可以有为也。以中顺自固曰「巩用黄牛之革」，此周文王心离初为黄牛，阳外为革。巩，固也。初以阳德居离明先，非才之不可以有为，谓谨守中顺，然后上合天心耳。周文巩用夷齐来归，天下大义于是而正。</p><p>六二，巳日乃革之，征吉，无咎。象曰：「巳日革之」，行有嘉也。桀纣之恶著，伊尹、太公不得已而与商周，令闻令望，传于后世。商周之革，二臣之力也。其征吉，诚以契天人之心耳。二离中有文明德，是以能上应九五，敷大信于天下。离于时为亨，曰「行有嘉」。</p><p>九三，征凶，贞厉。革言三就，有孚。象曰：「革言三就」，又何之矣？汤武之师，吊民而止。革道既成，过中则残，必贞必厉，始合天心，武不可黩也。夫「革言」而就者三，众信之，天下归之也。抚以宽仁，斯为「贞」矣。武之归马放牛，示天下弗服；汤之栗栗危惧，若将陨于深渊，其「贞厉」之谓乎！兑体在上为言，三阳为三就，刚过为「征凶」。自三以往，有互乾体，皆曰「有孚」。如天在上，孰不信也。</p><p>九四：悔亡，有孚，改命吉。象曰：「改命」之吉，信志也。</p><p>处互乾中，其革当天下信之，信其为天下心也。以我明德，易彼昏政，曰「改命吉」。互体巽位，居水火相息之际，为「改命」。四不正，本有悔，得乾中而「悔亡」。</p><p>九五：大人虎变，未占有孚。象曰：「大人虎变」，其文炳也。文王道德之化默施天下，天下靡然从风，所变者大，不待质之鬼神而其道已孚，无他，躬行之应也。兑西方为虎。兑互离龟为占。呜呼！纣之不道，文王已革之于先矣。观诗汉广德教所及，汝坟道化所行，其为孚也，岂待占而后知哉！上六：君子豹变，小人革面，征凶，居贞吉。象曰：「君子豹变」，其文蔚也。「小人革面」，顺以从君也。</p><p>其汤武事乎？兵不戢，将有自焚之灾，曰「征凶」。治之以仁义为「居贞」。礼法刑政密矣，曰「其文蔚」。考周公训迪顽民辞，凡欲革其心也。兑说见于外为「革面」。䷱ 巽下离上 鼎：元吉，亨。</p><p>彖曰：鼎，象也，以木巽火，亨饪也。圣人亨以享上帝，而大亨以养圣贤。巽而耳目聪明，柔进而上行，得中而应乎刚，是以元亨。</p><p>圣人有明德，而群才乐为之用，仁德并施，海内大治，曰「鼎，元吉，亨」。风自火出为家人。礼明于内而化行于外也。家道正而天下治。鼎象治道之成，明德升于上，人才用于下，坐收调一之功，其吉也大。巽木为才，鼎之才，家人之化也，故鼎治自家人始。然则正身以齐家，齐家以治天下，真古今不易之道欤！鼎，象也，以木巽火，亨饪也。鼎当求之象而不求之器。鼎象天下。夫天下，大器也，虚器也，扶持纲纪之在人。圣人治天下，不自恃其明，用众才为明。曰「以木巽火」，贤才用而吾明德以著，教化以行，「亨饪」之功于是成矣。阳实为饪，圣人亨以享上帝，而大亨以养圣贤，亨饪之见于事者也。夫人才并用，治道聿兴，上可当天心，下可育人物，其效顾不博大哉？必曰「大亨」，治大成也。互乾发享帝义，乾刚为圣贤，盖人生宇宙闲，导而使为圣为贤，在上养之何如耳。圣人之治，孰有大此者乎？「巽而耳目聪明」，言圣人体巽用才，而明德之大，蔑有加也。且敛天下聪明而归诸己，非巽以下贤者，莫能行之。夫惟内巽其志，外巽其身，则善道日闻，下情上达，不复有壅蔽之患，何施何为而不中于理也，天下其有不治邪？卦自离变，伏坎在下，坎为耳，离为目。曰「巽而耳目聪明，柔进而上行」，其道进也。自巽而离，曰「柔进得中而应乎刚」，应上下之刚也。六五以明德处互乾上，道虽用柔，身履乾刚，是以能应。得中应刚，鼎道成于是矣。盖刚中之贤应，然后可与大有为于鼎，以尽用天下之才，而大吾明德也。或曰鼎自遁来，二阴卦也，何以为鼎？曰遁二阴位穷于上，是谓大壮。鼎为卦，大壮之上来居鼎初，大壮之初往居鼎上，刚贤用事，君道得中，鼎大壮之效也。群贤并用而位乎上下，鼎治其昌矣。</p><p>象曰：木上有火，鼎；君子以正位凝命，分定而后礼化行。孟子曰：「中天下而立，定四海之民。」正君位以正天下之位，使贤不肖贵贱人心各安其分，而不相错乱，命其凝矣。盖治莫大于分，圣人敛贤才而布之天下，非正位于上而动无非礼，何以一天下之志，而纳之中和之治哉？惟夫位得其正，群贤在列，各当其序，君命以定，礼化遂行。离南方，为礼，为正位。巽在下，为凝命。巽为命，巽阴为凝。</p><p>初六，鼎颠趾，利出否。得妾以其子，无咎。象曰：「鼎颠趾」，未悖也。「利出否」，以从贵也。居鼎初有取。新义曰：「鼎颠趾」，颠趾非鼎之正，利在出否；得妾非家之正，利在得子。且鼎继革后，必去其浊秽，而后饪可亨也。譬士乘风云之会，虽起鱼盐屠狗，所不当问，生化之功系以成，曰「以其子无咎」，其事非正，其理未悖也。初以阴居三阳下，为颠趾，巽下为妾，三阳在前为子，阳有生物之德为无咎。阳为贵，应四为从贵。九二，鼎有实，我仇有疾，不我能即，吉。象曰：「鼎有实」，慎所之也。「我仇有疾」，终无尤也。</p><p>刚中履正义。不苟从曰「有实」。阳为实，怨耦曰仇，指四言之。四折足为疾，四处近臣位，亢满不正，阻蔽二阳之进，而擅权用事于鼎，我之仇也。九二操德守义，惧四即之，故获吉。天地间终能济亨饪之治。「慎所之」云者，以其心之必将应五也。夫人臣而所适应之正，何尤之者。九三，鼎耳革，其行塞，雉膏不食。方雨亏悔，终吉。象曰：「鼎耳革」，失其义也。</p><p>四阻之，其道不得上行为耳革。乾金离火乘之为革。获应而后吉，曰「方雨亏悔终吉」，言遇上而吉也。鼎自离变，离文明为「雉膏」，反兑为不食。忠嘉之德未获信用于上，曰「雉膏不食」。互乾天气下降，阴承之为方雨。雨则遇，遇则悔亏，为「终吉」。甚矣！小人为君子患而扼其进也。故君子虽有美德，莫获展尽，小人扼之而已，人主可不深念哉！失其义谓可举。鼎在铉，辅铉在耳，耳革而行塞，则失协济之义。吁！若三者，非上以刚德力振之，又安能有行于时，而终保其吉也哉？是以古之君子，必贵夫汲引之助也。</p><p>九四，鼎折足，覆公𫗧，其形渥，凶。象曰：「覆公𫗧」，信如何也。四以离初处互乾上，乾阳在下，鼎实也。四在三阳上，所受过量，其位不中，才德皆不能胜任，而窃居上位，是以有覆𫗧之凶。且四阻二阳之进，而专应初，弃阳从阴，谓邪为正，谓小人为君子，恣其邪心，上下莫之孚信，卒败鼎事，固其宜也。圣人以天下大器不可付之匪人，而辨之宜早，丁宁力言之，使后世知以取训。不然，祸至徐图，为社稷百姓忧，莫可悔矣。呜呼！观大臣者必考其信，盖信不足则欺，必将蔽贤援不肖，以重违天人之心。使如斯人而获用，几何而不肇乱产祸邪？四应初，初以阴在下，为折足。离雉为𫗧，互兑，兑毁为覆𫗧。兑泽为形渥。渥，沾濡貌。夫鼎而覆𫗧，则无以享上帝、养圣贤，至天下不得食矣，凶其大哉！</p><p>六五，鼎黄耳金铉，利贞。象曰：「鼎黄耳」，中以为实也。五位离中，其德文明，而又下有刚德，臣为之正应，以辅成其德，举天下之大而措之治，有余裕矣。且天下治乱，率由人君听纳之得失。五得中而明，虚己以听，是以九二刚贤乐为之用，而吾之明德由此日新，鼎治于是成焉。曰「鼎黄耳金铉」，所以举鼎。金，西方至坚之物，其质不变而有常，刚德之譬也。盖天下大器，非刚莫举，五虽柔位，乾刚承之，柔进上行，刚复往应，故曰「金铉」云。互乾在下为金。「利贞」，盖勉以贞固之道也。呜呼！天下虽大，其治不难致也。以中听，以刚举，天下何患不治？中故无不用之贤；刚故无不举之治。鼎之为鼎，殆将功用不穷矣。</p><p>上九：鼎玉铉，大吉，无不利。象曰：玉铉在上，刚柔节也。尧舜尽道，进于帝矣。道者何也？皇极之中也。玉为物，温润而坚，曰「玉铉」。盖必有中和之道，中和之化，中和之治，熙熙乎尧舜时矣。金铉举天下以刚，玉铉举天下以中，帝王之治于此分。上本乾位，六五柔中，进而承之，粹美积中，而德益盛，业益大，为玉铉。乾为玉，为金。「刚柔节」，谓五承之也。䷲ 震下震上 震，亨。震来虩虩，笑言哑哑。震惊百里，不丧匕鬯。彖曰：「震」，亨。「震来虩虩」，恐致福也。「笑言哑哑」，后有则也。「震惊百里」，惊远而惧迩也。出可以守宗庙社稷，以为祭主也。</p><p>上坤下震为复。复其一在内，虽动而静，至震则内外俱动矣。四下应初，是曰「震来」。四动互坎，中且有互艮体，止动不宁，其来也恐，而阳气奋达，万物以生，其恐斯福。曰「震亨」。震，动也。在人吉凶悔吝所自生也。动而畏天，必获后福。虩，动物之周旋观视者。阳之未升，不无虩虩之虞。虩虩，忧也，钦也，畏也。阳动于一，浸至于泰，中和之气自是而达。曰「笑言哑哑」，阳动为「笑言」。夫人君动而临莅天下，而能知天之畏，常若天威咫尺，肃恭之心不替，斯须则德进身修，行为天下式，言为天下法，薄海中外，是则是傚，罔不知悦矣。故曰「震来虩虩，恐致福也。笑言哑哑，后有则也」。此继天为子事也。「震惊百里，不丧匕鬯」谓何？震长子主器，有动而代天之象，不必专主储贰言之。夫惟动而畏天，钦诚所格，远迩耸服，于守国何有？生养之功，自是兴矣，故曰「不丧七鬯」。七鬯，有中和美德，而可以养人者也。且君子之道，本之身而施之人，由吾省惧，使远迩皆知省惧，天下迁善远罪，自我化之，是为震惊。震惊而止曰百里，盖由迩而远，其动不息，所及者大，自百里而及千万里也。惟震惊百里，故德通于神，鬼神歆享，社稷有磐石之固，宗庙以享，子孙以保。系辞曰：「帝出乎震。」震动而有为时也。乾坤功用付于震，犹人君配天地而为之子也。人君必上畏于天，而后天下知畏于君，而七鬯以守。盖畏天则德积于身，动无过举，天下孰不肃畏而回心乡道，以从我之化哉？震一变坤，坤为邑，为百里，七以举鼎实。鬯，郁鬯也。其色中互艮，艮手；互坎，坎酒食，为匕鬯。</p><p>象曰：瀳雷，震，君子以恐惧修省。</p><p>圣贤畏天之学，肃肃祇祇，如天威常在其上，常在其左右，而思以迁善悔过，德如之何而不盛哉？雷不一曰瀳。初九，震来虩虩，后笑言哑哑，吉。象曰：「震来虩虩」，恐致福也。「笑言哑哑」，后有则也。</p><p>初为震动主，动以钦畏，道不违天，故天下取则，而说在动后，其理固然也。</p><p>六二，震来厉，亿丧贝，跻于九陵，勿逐，七日得。象曰：「震来厉」，乘刚也。</p><p>刚动于下，二以阴乘之，在震处此甚难，刚阳浸长，必丧其资，惟应五斯不失臣道之常。「七日」，爻之一气周也。居震动时，为臣当一心诚意，上应于君，忠嘉乃著。不然，名实俱丧，为天下后世罪人矣。变离为贝，五在互艮上为九陵。九，阳数，贝所资之利也。周公遇管蔡之变则然，当是时，厉其孰大！</p><p>六三，震苏苏，震行无眚。象曰：「震苏苏」，位不当也。</p><p>在震必恐惧省己，尽力于诚一之德，而后其动无过，足以息变兴利于震。三以阴居下卦，上有互艮体，钦慎之心止矣。惟震行不息以充其道，眚乃亡也，可不勉邪！夫士君子立人之朝，于震动有为时，而不磨砺德业，以趋赴功名，会天地鬼神之责将及之，而况于人乎？眚得免哉。苏苏，志意舒缓貌也。互艮，自艮而震，为震行。</p><p>九四，震遂泥。象曰：「震遂泥」，未光也。</p><p>处四阴中，其道未申，曰「震遂泥」，君子必慎所与，不然，虽有刚动之才，不克施为矣。群阴退听，其道始光也。呜呼！大臣欲有为于天下，莫先于亲君子，远小人，以辅助其刚德，此而不图，何以享令望于天下后世哉？互体坎，坎为泥。互艮，阴陷之，为未光。</p><p>六五，震往来厉，亿无丧，有事。象曰：「震往来厉」，危行也。其事在中，大无丧也。</p><p>六五进则遇上而动极，退则乘四而履刚，往来震动之间，有坎险体，其理危甚。而五以柔居震动中，是能损己修德，汲汲兢兢，不以天下为乐，而以为己忧者，中和之气足以息强暴，镇浮俗，不独变故可尽弭，而事业之大从此兴矣。宜圣人叹嘉，谓无失德于天下，而可以大有为于震也。互坎坎，信为无丧。呜呼！人君处震动时，亦在夫躬至诚不息之德以勉其中。中者，天所与，人所归，中则自身施之天下，无不当于理而顺于人。易道尚中，周成东征之后，不敢自逸，王业更昌；宣遇灾而惧，王化复行。二君以柔中得大无丧义云。</p><p>上六，震索索，视矍矍，征凶。震不于其躬，于其邻，无咎，婚媾有言。象曰：「震索索」，中未得也。虽凶无咎，畏邻戒也。上六以阴居互坎上，处震动之极，莫知所安，故志穷于内，目动于外，若是者，自守犹惧凶也，况征乎？且己在震上，有其位矣，而心不得须臾宁，凡以不得中道耳。夫得中则诚，诚则事事中理，俯仰之间，了无愧怍，何「索索」「矍矍」之为哉？「震不于其躬，于其邻」，不待祸灾及己而后悔悟也。视邻以戒，邻之中我以为中，斯「无咎」矣。夫自一国以至于天下，当震动扰攘之极，才德不足以弭之，傥非亲比有德，迁善悔过，何以自保也？「婚媾有言」，谓三。三正应也。舍三从五为「有言」。君子于震，从其正而已矣，言奚恤乎？阴居动极为「索索」，为「矍矍」。震目为视，反艮为躬。邻谓三。五，有互坎体，水㶁㶁成声，为「有言」。䷳ 艮下艮上</p><p>艮其背，不获其身。行其庭，不见其人，无咎。</p><p>彖曰：「艮」，止也。时止则止，时行则行，动静不失其时，其道光明。「艮其止」，止其所也。上下敌应，不相与也。是以「不获其身，行其庭，不见其人，无咎」也。</p><p>乾阳中于坎，止于艮，动于震，终终始始，生化不穷。「艮其背，不获其身」，忘己也。阴为腹，阳为背。圣人止德于静，其心泰然，与天地为一。曰「艮其背，行其庭，不见其人」，已忘而物亦忘之也。盖静而后能止，我止而天下万物莫不各止其所矣。夫艮，万物潜冥时也。圣人法之，体道之静，天下事物莫或干焉。曰「不见其人」，圣人岂绝物而漠然不与事物接哉？惟其深明夫物我之分，内不知有己，视天下若无与，是以因时而动，酬酢万变，不失其中，而可以参配天地生物之德，天下莫窥其应用之迹也。古人绣黻于裳，两己相背，正取止静之义，以示至戒。有天下者不可不知艮。盖止静则性复于一，耳目声色之好不萌于心，而累德者去。其出而临莅天下，若出于不得已，而莫不以礼法从事，惠利之及于天下万物，岂可一二胜言哉？艮，止也。时止则止，时行则行，动静不失其时，其道光明。艮其止，止其所也。上下敌应，不相应也。是以「不获其身，行其庭，不见其人，无咎」也。申言艮之所以为艮也。真止不系动静，故行止因时，而动静当于道，道以光明。万物屈于丑，申于寅，动以静基，而发生大德，著见于外，曰「动静不失其时，其道光明」。圣人用艮于身，而得夫真止之道，动静应天，事业以大。盖由吾一性之光明，已极夫天下之光明也。尧之光被四表，舜之重华协于帝，皆自真止中来。书称尧安安，传称舜「幸能正生，以正众生」。其君臣相警戒，亦曰「安汝止」。尧舜盖深得于易者。且夫子固尝用艮矣，可仕则仕，可止则止，可久则久，可速则速。夫子之道，昭明于天下后世，亦以性止于内，故动静无往不当也。艮其止，止其所也。上下敌应，不相与也。此以卦体论。艮一阳止于外而在上，二阴止于内而在下，上下敌应，无一不止其所安，斯无咎之道。互震坎为动静，阳上为光明。坎险则止，震动则行，为时止时行。象曰：兼山，「艮」，君子以思不出其位。</p><p>夫山至静，而云物兴焉，渊泉出焉，草木生焉，禽兽居焉，货财殖焉。人止心于静，功用之及于天下，殆未可测也。君子观艮象而安于所止，是以心念至正，有所不动，动斯光矣。「思不出其位」谓何？为人子思孝，为人臣思忠，在士思学，在朝廷思治，在上思所以利下，在下思所以事上。夫子著「思无邪」之训，自艮发之。若曰不出其分位，是畎亩之间不容有拳拳思忠者邪？兼山内外俱静义。艮土为思。</p><p>初六：艮其趾，无咎，利永贞。象曰：「艮其趾」，未失正也。在艮而止于下，夫何咎？「利永贞」，戒也。盖士君子进为于时，以知止为本。夫不知止，鲜克有终者，情欲内牵，势利外诱，则无往能止。心不知止，而一肆其所行，尚何惠利之及人哉？是不可不贞于蚤而持以久也。阴下为趾，柔初而能止，为未失正。</p><p>六二：艮其腓，不拯其随，其心不快。象曰：「不拯其随」，未退听也。</p><p>其德中正，又时位当可行，莫或拯之，而录录随人，曰「不拯其随」；眷眷然有不忘君心，曰「其心不快」。夫更相汲引，皋夔盛事也。九三履刚，曾不下其听于二，惑哉！若二之中德，三或援之，可以应五，而有行于艮，不拯若何？阴居下为腓，阳止其位为不拯。互坎，「坎」心病，为不快。盖腓在下，必股肱拯之，然后能有行耳。呜呼！君子之急于得君，盖欲以行道，彼固非若小人求快其私志也。二其忠于事君，果于立事者哉！</p><p>九三，艮其限，列其夤，厉薰心。象曰：「艮其限」，危薰心也。艮一阳居上，阳止其所，得止静之道，因而重之。三位在四阴中，有互坎、互震体，为「艮其限，列其夤，厉薰心」。爻言变也。身中曰「限」，上下之气所自达也。三处内卦上，不安分位，有乘险以动，壅塞正道之心，于止静失矣。且小而一身之否，大而天下之否，莫不皆自夫上下之情气不通，而上下之情气蔽隔不通，以有物间之耳。在人则邪气为身害，在天下则小人为天下害是也。三刚过不正，陷四阴中于「艮」，盖小人之雄者。夫小人能为国家患，必才过人者能之。彼徒切切然经营于胸中，日以壅塞正道为务，事几一发，大而亡人之国，小而亡己之身，可不畏哉！居下体上为限，夹脊肉为夤，阳止为列，阴阳之气窒不通为薰心。九三以阳居阳，譬小人之有才，而能蔽塞贤路，以危其君者，是以取象若此。心为君，互坎为心。六四，艮其身，无咎。象曰：「艮其身」，止诸躬也。</p><p>「艮」以「不获其身」为义，盖圣人忘己以应天下之道也。四位失厥中，未能融物我为一，方致力于修其身而已。用止于身，自守以正，动遵礼法，曰「艮其身」。四以阴居阴，才德俱不足，不能举天下而尽纳之正，是未可任天下之重，而应天下之变也。于己无咎，位则未称。圣人曰「止诸躬」，谓躅躅然从事于一己之修，德未加于人耳。虽然，四知身之止而行以不息，庶几亦可以辅成其君之德，故「无咎」。阳在下为「止诸躬」，盖所止在一己之辞。</p><p>六五，艮其辅，言有序，悔亡。象曰：「良其辅」，以中正也。「辅」，车之辅。人主安危荣辱之机在言，一失其序，左右者得以窥伺，而谗闲疑隙所生也。况发号出令，将以止天下之动，安可不重慎其言以自贻悔哉？夫惟止静之功既成于性，而中正之道内足于身，发之于言，言必尝道，悔其亡矣。呜呼！人君不可不知止也久矣。为君而不知止，则事物惑之，谄佞移之，声色蔽之，玩好夺之，殆将沦于不中不正之域。故心不诚于言，言不得其序，今日是之，明日非之，虽纷纷多言，谁其信从也哉？艮六爻象皆取诸身，人之相感，与夫行止动静之几，莫切于身。爻位上下，象体自具。五下乘互震，上止下动，有颐象，为辅；互坎在下，为言。虽然，圣人不言而化，化在言前，盖其躬行之实，有以感之于先，不待言也。五柔中，仅能用中正以见于言而已，未可以语化，化其大乎？</p><p>上九，敦艮，吉。象曰：「敦艮」之吉，以厚终也。</p><p>因性之正而加止也，淳之至也，利物之德兴矣。其存心厚，其行事亦厚，内外两尽，而生养之功施于万物，配于天地。臣道有终，莫过于此。盖居止知止，则少欲于身，而公道行于天下，利物之德可量也哉！古人于晚节尤加慎畏，夫失性不知止，不能保厥终也。良自坤索为「敦」。䷴ 艮下巽上 渐，女归吉，利贞。</p><p>彖曰：渐之进也，「女归吉」也。进得位，往有功也。进以正，可以正邦也。其位，刚得中也。止而巽，动不穷也。</p><p>渐，否之变，坤三上行，乾四下承。男下女，女归之，其归以礼，是谓「女贞」。渐，臣道也。卦象「女归」，以贞为本。爻象「鸿渐」，则以其进有序为义。互离在中，离为日，为明。君明于上，时可进矣。进得位，往有功也。进以正，可以正邦也。言君子之进不苟也。坤阴位，巽下为得位。仁德内止，上通于君，位与德称，利泽其大，是以有功。生物之功，起于震巽，为有功。「进以正」，谓上仁下顺，上下交孚，以礼而进，有回天格心之功，无顺旨阿谀之事。君臣之间，用无失德于天下，而天下从其正，曰「进以正，可以正邦。其位，刚得中也」。指五言之。盖君有刚中之德，而后可与有为于时。臣之进也，恃此而已。如是而后能行其正，而巽动不穷也。终言渐进之道也。艮七变为渐，而艮在内，巽在外。渐以艮止立本，以巽仁行之，德止事顺，功业其兴矣。盖人臣进为于时，莫病乎躁动不知止，方且得失利害交战胸中，尚焉能择义而行，以尽其爱物之仁哉？知止则定，定则能应，度时而动，徐以尧舜仁义之道启沃君心，鲜不入矣。是以上得于君，且能有所建立于天下，功业之兴，无有穷已也。</p><p>象曰：山上有木，渐，君子以居贤德善俗。德修之身，可以芘人，譬木在山，山止于下，木渐于上，积非一日，贤德必居，乃能有化。孟子曰：「居天下之广，居宅而行之之谓居。」贤德，仁德也。德非止乎仁，善俗，仁德之施也。艮山为居，巽风鼓舞为善俗。</p><p>初六，鸿渐于干，小子厉，有言，无咎。象曰：「小子之厉，义无咎也。</p><p>柔处艮下，其进为难，知难而厉，义无苟合。或者不察，惟急于应，是以有言处己，苟当言，无伤也。且士君子之进，当致难于初，不然，幸进喜得，外行险，内愆义，以重获罪于天人，君子不为也，厉其贵哉！渐自艮变，坎离在中。鸿，水物，其色文明，飞有序，来有时，故渐六爻皆况鸿。初位互坎下为干，艮下为小子，四居互兑中为有言」。干近水，言厥进甚徐，不敢轻也。</p><p>六二，鸿渐于磐，饮食衎衎，吉。象曰：「饮食衎衎」，不素饱也。身安道行，君子乐之，食人之禄，可以无愧矣。二本坤中，得臣道之正，曰「鸿渐于磐」。互坎为饮食，艮中为磐。磐，石之安平者。盖五以刚中应二，而二得行其志，故身安志舒，饮食衎衎。「衎衎」，舒和貌也。孔子曰：「邦有道，谷；邦无道，谷，耻也。」若二其食粟于有道时，而言听计从欤？不然，何为衎然其和，而了无愧怍于心也。呜呼！士君子之进，而志不得信于上下，不肯一朝安居矣。诗曰：「彼君子兮，不素飧兮」，二之谓矣。</p><p>九三，鸿渐于陆，夫征不复，妇孕不育，凶。利御寇。象曰：「夫征不复」，离群丑也。「妇孕不育」，失其道也。利用御寇，顺相保也。</p><p>易以夫妇象君臣，三舍乾阳趋坤阴，于道为远。且三四以相比而私亲，非以应相求也，安能成生育功邪？譬夫君臣之间，本非志合道同，而遇不以正，鲜能成事矣。「利御寇」谓何？四顺比三，缓急有相保势，而开国承家之君，则非所当用也。三四在卦体象「归女贞」，爻言其变。圣人复以乾坤自否相交，发君臣进合不以道，示为臣大戒。夫鸿渐于陆，进得位矣。而君背道，臣无治功之实，徒以顺亲比。借曰「御寇利」，终非为国之利。盖君臣之遇不正，固无以正天下也。互离，离南方，为陆。三以乾居互坎中，坎险背道，阳止于下，为不复。四自坤居互离中，其性顺丽，无治功之实。离复为妇孕，坎盗为寇，离坎不相济，为不育。且「坤」进上行，失母之道，是以不育也。</p><p>六四，鸿渐于木，或得其桷，无咎。象曰：「或得其桷」，顺以巽也。位高，危道也。履高位而至安，其惟顺乎？且君子所谓「顺」，顺于道，非顺于事。顺于道，故其感人深，而君安之，吾身亦以之安。「巽」木为桷，「桷」，平柯也。或云者，得之难也。「公孙硕肤，赤舄几几」，诗人咏周公四，其是哉！四有离明体顺巽，盖所优为自坤之「巽」，曰「顺以巽」。</p><p>九五，鸿渐于陵，妇三岁不孕，终莫之胜，吉。象曰：「终莫之胜，吉」，得所愿也。</p><p>间除道合，生化之功于是成。曰「终莫之胜，吉」。盖二五得刚柔之中，君臣皆有中德，「睽」必合。自二至五，历三位而应，为三岁。「三岁不孕」，三与四实间之也。「艮」上为陵，三四位不中正，为「终莫之胜」。夫「渐」，臣进之卦，而二五居乾坤中，得君臣正位，志同道合，卒得所愿，臣之获进，斯为盛矣。</p><p>上九：鸿渐于陆，其羽可用为仪，吉。象曰：「其羽可用为仪，吉」，不可乱也。</p><p>「巽」上何以为「陆」？「巽」位东南，陆也。位在上而与三同曰「陆」。美哉！盛德事也。盖大臣以谦恭自处，而礼行于身，有安平之德，无高亢之累，则进止施为皆有法度。行之天下，施之后世，莫不视为楷式，不可少易，孰吉如之？诗美周公「鸿飞遵渚」、「遵陆」，卒章曰：「是以有衮衣兮，无以我公归兮，无使我心悲兮。」谓其仪刑可法也。巽白为羽，互离文明为仪，为不可乱。䷵ 兑下震上 归妹：征凶，无攸利。彖曰：归妹，天地之大义也。天地不交而万物不兴。归妹，人之终始也。说以动，所归妹也。「征凶」，位不当也。「无攸利」，柔乘刚也。</p><p>阴阳之义，必始终相续，然后生生化化，其道不穷。此归妹设卦之旨也。节之在礼，守之在中，故「征凶」。不然，说动不已，而失顺静之道，何以能久？惟臣之于君亦若是。夫英才遇时，有说动之志，而不知谨礼揆中，若后世汉贾生蔑视绛、灌，纷改制度，事功亦何从而立哉？宜「征凶」之所以致戒欤！归妹，天地之大义也。天地不交而万物不生。归妹，人之终始也。圣人释彖辞，未有若此深切著明而特发其义者，要使后世明天地之道，察男女之情，而用之于君臣之间，可以长久而无不继之弊也。天地交为泰，其至和之气复相交于中为归妹。生化之理于是滋出，生物之义斯为大。圣人知泰必有否，稽诸天地，以究夫时运之所以终始，而反复言之。且坤位西南，乾位西北，兑居坤乾之间，万物至是而摇落，归根时也。乾三上进，坤四下承，而发震、兑二象，是为归妹。自兑而往，乾阳用事，中男之坎，少男之艮，承父以大其生物之德，终终始始，无有穷极，生理昌矣。故夫夫妇君臣之道，不继则息。礼之有娣妹，所以求继。而人君于英才勤勤下之，盖将以为天下社稷长久无穷计也。三四相易，阴阳各失其位，曰位不当。夫失位而说动不已，则柔之所遇不一，将舍震阳而有下从二刚之心，生化之功，或几乎绝灭，能无凶乎？惟安静不征，然后获所归，而终始之道得也。</p><p>象曰：泽上有雷，归妹。君子以永终知敝。</p><p>雷动泽应，说感以正，利物之功益大，非若雷风之为恒也。君子法之，事图厥终，归妹永终之道也。内而一家，外而天下，生生化化，其理惟均。「知敝」云者，谓不然则生化之理或几夫绝灭耳。</p><p>初九，归妹以娣，跛能履，征吉。象曰：「归妹以娣」，以恒也。「跛能履吉」，相承也。</p><p>兑下为娣，兑毁足为跛，承二为能履、为吉。二以刚得中，女子之贞者，所承既贞，何动不吉？且士君子固有因大臣之援以遂其进为之志者，斯亦分义之常，惟适从之正，乃能有行有为于时也。慎哉！</p><p>九二，眇能视，利幽人之贞。象曰：「利幽人之贞」，未变常也。离为目，为视，兑毁之为「眇」。二以互离居兑中，若眇者之有见，然其德本明，其毁外至，曰「眇能视」，泽中为「幽人」。夫九二以刚履柔，位又得中，用离明，乘兑毁，在「归妹」为德胜而容貌不足动人者，惟遵晦守贞，待上之求，斯不失其常。圣人设此爻以明归妹说动之极，苟不知以德守贞，失女子之常，则无以保终获吉于后也。吁！为人臣当「归妹」时，上动以求，下说以应，谓可进矣。然一于进而不知守其常德以待际遇，其势必不能久合以取信于上，且敷大利于下。故士君子虽容貌阀阅，不足动人，苟有中德，要当自晦，君我信而后应之，始能有为于天下。傥说动不贞，以至丧己招辱，何往而见其利也哉！</p><p>六三，归妹以须，反归以娣。象曰：「归妹以须」，未当也。六三自坤四来，「归妹」所由以成卦，而德位俱不正，故发此象。「须」，贱妾星也。织星贵，须星贱，譬夫士起微贱而进不以正，何补于用？「反归以娣」，始为合礼。「反归」，谓反从初也。从初而得承二之正，斯为当矣。孟子有父母国人贱之之喻，其须之类欤！三丽于二阳之间为「须」。</p><p>九四，归妹愆期，迟归有时。象曰：「愆期」之志，有待而行也。四居兑上，兑正秋，为「愆期」；至震而动，为「有时」。夫君子之心不一日忘天下，岂固于进而难之哉？顾进非其时，则无以遇合而行其志，是君子必艰于进。震位东方，君子至是可以行其仁矣。</p><p>六五，帝乙归妹，其君之袂，不如其娣之袂良。月几望，吉。象曰：「帝乙归妹，不如其娣之袂良」也，其位在中，以贵行也。</p><p>「归妹」自泰来，故五爻辞与泰六五同，曰「帝乙归妹」。「君」谓二，「娣」谓初。乾为衣，初、二本乾体，其象取「袂」。「袂」饰礼容之服。互体「坎」，「坎」为月，「月几望」，谓德明而守之以谦也。妇事夫，臣事君，亢则累夫。小君有谦中之德，而妇容则下于娣。君子何贵哉？贵夫德而已矣。「帝乙」，尊者。称尊者而曰「乙」，取屈体待下义，以贵行贵德也。盖五位在中，故所归者亦贵于中。鸣呼！自昔有天下者，英才必相继以进，然后治功可永。古人所以甚恶夫窃位，而贤君礼贤求士，心不敢须臾忽，正谓此耳。然人才以德为贵，此帝乙归妹之心，傥舍德而取其文采容貌之末，祗以害治，非所以成治，尚何所用于归妹哉！</p><p>上六：女承筐，无实，士刲羊，无血，无攸利。象曰：上六「无实」，「承」虚「筐」也。</p><p>不诚何以相与？君臣、上下、夫妇率以此败。女谓三，士女云者，夫妇之道「睽」也。震为竹，筐，竹为之，其形方，阴数也。三以阴承震为「无实」，兑为羊、为金，互坎在上为「无血」，见上之不诚于三云。上下不以诚，遇何以久，尚安能成生化之功邪？序卦曰：「进必有所归，故受之以归妹。得其所归者必大，故受之以丰。」归妹，贤才迭进卦也。彖辞首以「天地不交则万物不兴」为训，然则大臣而专禄固宠，窃有其位，而不汲汲于援引贤才以辅其上，譬由天地既泰，而其气不复交也。生生之理不几于息而重违天地之心乎？紫岩易传卷五，</p>',154)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
